/**
 * Emit the adapter's stdout response for a final decision.
 *
 * - allow → adapter.formatAllow(event)
 * - warn  → adapter.formatWarn(reason, event) if defined, else formatAllow
 * - deny  → adapter.formatDeny(reason, event); reason is derived from local rule
 *           IDs or, on a gateway deny, extracted from the gateway response body
 *           (falling back to a generic "Blocked by Oculi gateway").
 */
function writeDecisionOutput(
  adapter: import('./routes/adapters').HookAdapter,
  event: import('./routes/adapters/schema').OculiEvent,
  decision: 'allow' | 'warn' | 'deny',
  localRuleIds: string[],
  gatewayBody: string | undefined,
): void {
  if (decision === 'allow') {
    process.stdout.write(adapter.formatAllow(event));
    return;
  }

  if (decision === 'warn') {
    const warnReason = `Oculi warning: ${localRuleIds.join(', ')}`;
    const warnOutput = adapter.formatWarn
      ? adapter.formatWarn(warnReason, event)
      : adapter.formatAllow(event);
    process.stdout.write(warnOutput);
    return;
  }

  // deny — prefer reason extracted from gateway body; otherwise fall back.
  const reason = extractGatewayReason(gatewayBody) ?? 'Blocked by Oculi gateway';
  process.stdout.write(adapter.formatDeny(reason, event));
}

